def find_missing_primes(num_terms):
    a = [0] * (num_terms + 1)
    a[1] = 10
    for n in range(1, num_terms):
        a[n+1] = 6 * a[n] - 2**(n+2) - 3**(n+1) + 5

    factors = set()
    for val in a[1:]:
        d = 2
        temp = val
        while d * d <= temp:
            if temp % d == 0:
                factors.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            factors.add(temp)

    primes = []
    is_prime = [True] * (max(factors) + 1 if factors else 100)
    # Let's just find primes up to a certain limit
    limit = 10000
    is_prime = [True] * (limit + 1)
    for p in range(2, limit + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False

    missing = [p for p in primes if p not in factors]
    return missing, factors

